import{_ as n,o as s,c as a,a6 as t}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"开发环境准备","description":"Chrome 插件开发指南 · Chrome 版本、加载未打包扩展、推荐目录结构与工具链","frontmatter":{"title":"开发环境准备","description":"Chrome 插件开发指南 · Chrome 版本、加载未打包扩展、推荐目录结构与工具链","source":"https://daiw.org/manual/chrome-extension/environment-setup"},"headers":[],"relativePath":"manual/computer-programming/chrome-extension/environment-setup.md","filePath":"manual/computer-programming/chrome-extension/environment-setup.md"}'),r={name:"manual/computer-programming/chrome-extension/environment-setup.md"};function o(i,e,l,p,d,c){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="开发环境准备" tabindex="-1">开发环境准备 <a class="header-anchor" href="#开发环境准备" aria-label="Permalink to &quot;开发环境准备&quot;">​</a></h1><p>Chrome 插件开发指南 · Chrome 版本、加载未打包扩展、推荐目录结构与工具链</p><p>写扩展不需要特殊 SDK：一个文本编辑器 + Chrome 即可。本篇说明<strong>最低环境</strong>、如何<strong>加载未打包扩展</strong>做热调试，以及团队项目常用的目录与构建工具选型。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>10 课实战完整源码</strong>已开源：<a href="https://github.com/davidapp/chrome-extension-demos" target="_blank" rel="noreferrer">github.com/davidapp/chrome-extension-demos</a>。clone 后每个课次目录均可直接在 <code>chrome://extensions</code> 加载验证。</p></div><h2 id="直觉-像本地跑静态站-但入口是-manifest" tabindex="-1">直觉：像本地跑静态站，但入口是 manifest <a class="header-anchor" href="#直觉-像本地跑静态站-但入口是-manifest" aria-label="Permalink to &quot;直觉：像本地跑静态站，但入口是 manifest&quot;">​</a></h2><p>网页开发用 <code>npm run dev</code> 起服务器；扩展开发是告诉 Chrome：<strong>这个文件夹是一个扩展</strong>，Chrome 按 <code>manifest.json</code> 注册 Service Worker 和注入规则。改代码后大多数情况下只需<strong>在 <code>chrome://extensions</code> 点刷新</strong>。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>建议</th></tr></thead><tbody><tr><td>浏览器</td><td><strong>Chrome 128+</strong>（建议使用最新稳定版，如 Chrome 140+ / Edge 140+）；开发时打开 <code>chrome://version</code> 确认</td></tr><tr><td>编辑器</td><td>VS Code / Cursor；推荐扩展 <a href="https://marketplace.visualstudio.com/items?itemName=JuanFranBlanco.chrome-extension-manifest-file" target="_blank" rel="noreferrer">Chrome Extension Manifest File</a> 做 JSON 校验</td></tr><tr><td>Node.js</td><td>可选；用 TypeScript、打包、ESLint 时需要 <strong>Node 22+</strong>（与本站一致）</td></tr><tr><td>账号</td><td>仅上架商店需要 <strong>$5 一次性</strong> Chrome Web Store 开发者注册费</td></tr></tbody></table><h2 id="获取开源-demo-仓库" tabindex="-1">获取开源 Demo 仓库 <a class="header-anchor" href="#获取开源-demo-仓库" aria-label="Permalink to &quot;获取开源 Demo 仓库&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/davidapp/chrome-extension-demos.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrome-extension-demos</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>也可 <a href="https://github.com/davidapp/chrome-extension-demos/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">Download ZIP</a> 解压。仓库内 <code>01-hello-popup</code> … <code>10-offscreen-document</code> 十个目录与 <a href="/Front2Full/manual/computer-programming/chrome-extension/lesson-01-hello-popup">实战课程</a> 一一对应，每目录 README 含逐步操作说明。</p><h2 id="加载未打包扩展" tabindex="-1">加载未打包扩展 <a class="header-anchor" href="#加载未打包扩展" aria-label="Permalink to &quot;加载未打包扩展&quot;">​</a></h2><ol><li>打开 <code>chrome://extensions</code></li><li>右上角开启 <strong>开发者模式</strong></li><li>点击 <strong>加载已解压的扩展程序</strong>，选择含 <code>manifest.json</code> 的目录</li><li>修改文件后，在该扩展卡片上点击 <strong>刷新</strong>（或勾选「重新加载扩展」相关选项）</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-extension/</span></span>
<span class="line"><span>├── manifest.json      # 必需</span></span>
<span class="line"><span>├── service-worker.js  # 示例：后台</span></span>
<span class="line"><span>├── popup.html</span></span>
<span class="line"><span>├── popup.js</span></span>
<span class="line"><span>└── icons/</span></span>
<span class="line"><span>    ├── icon16.png</span></span>
<span class="line"><span>    ├── icon48.png</span></span>
<span class="line"><span>    └── icon128.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>加载目录后，<strong>不要删除或移动</strong>该文件夹；Chrome 记录的是路径。换机器请复制整个目录或改用 zip 打包加载。</p></div><h2 id="推荐目录结构-中小型项目" tabindex="-1">推荐目录结构（中小型项目） <a class="header-anchor" href="#推荐目录结构-中小型项目" aria-label="Permalink to &quot;推荐目录结构（中小型项目）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome-extension/</span></span>
<span class="line"><span>├── manifest.json</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── background/        # Service Worker</span></span>
<span class="line"><span>│   ├── content/           # Content Scripts</span></span>
<span class="line"><span>│   ├── popup/             # Popup React/Vanilla</span></span>
<span class="line"><span>│   └── lib/               # 共享工具</span></span>
<span class="line"><span>├── public/</span></span>
<span class="line"><span>│   └── icons/</span></span>
<span class="line"><span>├── package.json           # 若用构建工具</span></span>
<span class="line"><span>└── dist/                  # 构建产物（加载此目录）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>原则：<strong>开发时加载 <code>dist/</code> 或根目录二选一</strong>，manifest 里引用的路径与加载目录一致。</p><h2 id="工具链选型-可选" tabindex="-1">工具链选型（可选） <a class="header-anchor" href="#工具链选型-可选" aria-label="Permalink to &quot;工具链选型（可选）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>适合</th><th>说明</th></tr></thead><tbody><tr><td>纯手写</td><td>教程、极小扩展</td><td>零依赖，本章 <a href="/Front2Full/manual/computer-programming/chrome-extension/hello-world">Hello World</a> 即此路线</td></tr><tr><td><a href="https://wxt.dev/" target="_blank" rel="noreferrer">WXT</a></td><td>现代 TS 项目</td><td>类 Vite 体验，热重载、多浏览器目标</td></tr><tr><td><a href="https://www.plasmo.com/" target="_blank" rel="noreferrer">Plasmo</a></td><td>React 优先</td><td>框架感强，上手快</td></tr><tr><td><code>esbuild</code> / <code>rollup</code> 自配</td><td>已有 monorepo</td><td>扩展作为子包，完全自控</td></tr></tbody></table><p>本专栏示例以<strong>手写 MV3</strong> 为主，避免框架掩盖 manifest 细节；工程化篇再展开 <a href="/Front2Full/manual/computer-programming/chrome-extension/project-structure">项目结构</a>。</p><h2 id="调试入口速查" tabindex="-1">调试入口速查 <a class="header-anchor" href="#调试入口速查" aria-label="Permalink to &quot;调试入口速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要调试的对象</th><th>入口</th></tr></thead><tbody><tr><td>Service Worker</td><td><code>chrome://extensions</code> → 扩展卡片 → <strong>Service Worker</strong> 链接</td></tr><tr><td>Popup</td><td>右键扩展图标 → <strong>检查弹出内容</strong></td></tr><tr><td>Content Script</td><td>普通网页 DevTools → Sources → Content scripts</td></tr><tr><td>扩展页（options 等）</td><td>右键页面 → 检查</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>改 manifest 却不点刷新</strong>——多数 manifest 变更必须重载扩展；仅改 Content Script 有时刷新页面即可。</li><li><strong>路径写错</strong>——<code>&quot;service_worker&quot;: &quot;src/bg.js&quot;</code> 但加载的是 <code>dist/</code>，会报 <strong>Could not load background script</strong>。</li><li><strong>用 file:// 测 Content Script</strong>——部分匹配规则不对本地文件生效；用 <code>https://example.com</code> 或本地静态服务器。</li></ol><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><ol><li>Clone 开源 Demo 仓库（若仅跟 <a href="/Front2Full/manual/computer-programming/chrome-extension/hello-world">Hello World</a> 手写，可跳过此步自建空目录）：</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/davidapp/chrome-extension-demos.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrome-extension-demos</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ol start="2"><li>打开 <code>chrome://extensions</code>，开启<strong>开发者模式</strong>，确认能看到 <strong>加载已解压的扩展程序</strong></li><li>加载 <code>01-hello-popup</code> 体验第一课，或下一篇在空目录手写最小 manifest</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Chrome 128+、开发者模式、加载含 <code>manifest.json</code> 的目录，即构成最小开发环境。建议 clone <a href="https://github.com/davidapp/chrome-extension-demos" target="_blank" rel="noreferrer">开源 Demo 仓库</a> 按课次实战。记住 <strong>改代码 → 刷新扩展/页面</strong> 的循环。下一篇写出第一个可点击的 Hello World。</p><p>→ 下一篇：<a href="/Front2Full/manual/computer-programming/chrome-extension/hello-world">Hello World</a></p>`,32)])])}const u=n(r,[["render",o]]);export{m as __pageData,u as default};
